+    private Grid<Message> messageGrid;
+    private boolean hasUnsavedChanges = false;
+
+    @Autowired
+    public ContactView(MessageStore messageStore) {
+        this.messageStore = messageStore;
+        setDefaultHorizontalComponentAlignment(Alignment.START);
+        setPadding(true);
+        setSpacing(true);
+
+        // Heading
+        add(new H1("Contact"));
+
+        // Link to About view
+        Anchor aboutLink = new Anchor("about", "About");
+        add(aboutLink);
+
+        // Form
+        FormLayout form = createForm();
+        add(form);
+
+        // Grid
+        messageGrid = createGrid();
+        add(new Div(messageGrid));
+    }
+
+    private FormLayout createForm() {
+        FormLayout form = new FormLayout();
+        form.setAutoResponsive(true);
+        form.setExpandColumns(true);
+        form.setExpandFields(true);
+        form.setMaxWidth("36em");
+
+        nameField = new TextField("Name");
+        emailField = new EmailField("Email");
+        phoneField = new TextField("Phone");
+        messageField = new TextArea("Message");
+
+        // Track changes
+        nameField.addValueChangeListener(e -> {
+            hasUnsavedChanges = true;
+            sendButton.setEnabled(true);
+        });
+        emailField.addValueChangeListener(e -> {
+            hasUnsavedChanges = true;
+            sendButton.setEnabled(true);
+        });
+        phoneField.addValueChangeListener(e -> {
+            hasUnsavedChanges = true;
+            sendButton.setEnabled(true);
+        });
+        messageField.addValueChangeListener(e -> {
+            hasUnsavedChanges = true;
+            sendButton.setEnabled(true);
+        });
+        messageField.addKeyDownListener(Key.ENTER, e -> handleSend());
+
+        sendButton = new Button("Send", e -> handleSend());
+        sendButton.setEnabled(true);
+
+        form.addFormRow(nameField);
+        form.addFormRow(emailField);
+        form.addFormRow(phoneField);
+        form.addFormRow(messageField);
+        form.add(sendButton);
+
+        return form;
+    }
+
+    private Grid<Message> createGrid() {
+        Grid<Message> grid = new Grid<>(Message.class, false);
+        grid.addColumn(Message::getName).setHeader("Name");
+        grid.addColumn(Message::getMessage).setHeader("Message");
+        grid.setItems(messageStore.getMessages());
+        return grid;
+    }
+
+    private void handleSend() {
+        clearErrors();
+
+        // Validation
+        boolean hasErrors = false;
+
+        String name = nameField.getValue().trim();
+        if (name.isEmpty()) {
+            nameField.setInvalid(true);
+            nameField.setErrorMessage("Name is required");
+            hasErrors = true;
+        }
+
+        String email = emailField.getValue().trim();
+        String phone = phoneField.getValue().trim();
+
+        if (!email.isEmpty() && !isValidEmail(email)) {
+            emailField.setInvalid(true);
+            emailField.setErrorMessage("Enter a valid e-mail address");
+            hasErrors = true;
+        }
+
+        if (email.isEmpty() && phone.isEmpty()) {
+            emailField.setInvalid(true);
+            emailField.setErrorMessage("Give an e-mail address or a phone number");
+            hasErrors = true;
+        }
+
+        String message = messageField.getValue().trim();
+        if (message.isEmpty()) {
+            messageField.setInvalid(true);
+            messageField.setErrorMessage("Message is required");
+            hasErrors = true;
+        } else if (message.length() > 500) {
+            messageField.setInvalid(true);
+            messageField.setErrorMessage("Message must be at most 500 characters");
+            hasErrors = true;
+        }
+
+        if (hasErrors) {
+            return;
+        }
+
+        // Send message
+        Message msg = new Message(name, email, phone, message);
+        messageStore.add(msg);
+
+        // Show notification
+        Notification.show("Message sent");
+
+        // Clear form
+        nameField.clear();
+        emailField.clear();
+        phoneField.clear();
+        messageField.clear();
+        hasUnsavedChanges = false;
+
+        // Disable send button
+        sendButton.setEnabled(false);
+
+        // Refresh grid
+        messageGrid.setItems(messageStore.getMessages());
+    }
+
+    private void clearErrors() {
+        nameField.setInvalid(false);
+        emailField.setInvalid(false);
+        phoneField.setInvalid(false);
+        messageField.setInvalid(false);
+    }
+
+    private boolean isValidEmail(String email) {
+        return email.contains("@") && email.contains(".");
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!nameField.getValue().isEmpty() ||
+                !emailField.getValue().isEmpty() ||
+                !phoneField.getValue().isEmpty() ||
+                !messageField.getValue().isEmpty()) {
+
+            Dialog dialog = new Dialog();
+            dialog.setHeaderTitle("Unsaved changes");
+            dialog.add("You have unsaved changes. Do you want to discard them?");
+
+            Button keepEditing = new Button("Keep editing", e -> dialog.close());
+            Button discard = new Button("Discard", e -> {
+                dialog.close();
+                event.forwardTo("about");
+            });
+
+            dialog.getFooter().add(keepEditing, discard);
+            dialog.open();
+
+            event.postpone();
+        }
+    }
+}
